/* ==========================================================================
   EASTERN WORKFORCE SOLUTIONS ESTABLISHMENT - THEME & COMPONENT ADDITIONS
   ========================================================================== */

:root {
  --blue: #007bff;
  --indigo: #6610f2;
  --purple: #6f42c1;
  --pink: #e83e8c;
  --red: #dc3545;
  --orange: #fd7e14;
  --yellow: #ffc107;
  --green: #28a745;
  --teal: #20c997;
  --cyan: #17a2b8;
  --white: #fff;
  --gray: #6c757d;
  --gray-dark: #343a40;
  --primary: #007bff;
  --secondary: #6c757d;
  --success: #28a745;
  --info: #17a2b8;
  --warning: #ffc107;
  --danger: #dc3545;
  --light: #f8f9fa;
  --dark: #343a40;
  --breakpoint-xs: 0;
  --breakpoint-sm: 576px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 992px;
  --breakpoint-xl: 1200px;
  --font-family-monospace: SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono","Courier New",monospace;
  --background: #ffffff;
  --background-2: #009fe3;
  --background-3: #2f2f2f;
  --background-4: #be8d0e;
  --text: #212529;
  --text-2: #ffffff;
  --text-3: #5b5a5a;
  --accent: #009fe3;
  --accent-2: #007bff;
  --accent-3: #005373;
  --accent-4: #be8d0e;
  --border: #ffffff;
  --border-2: #dddddd;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 85px;
}

body {
  font-family: 'Open Sans', -apple-system, sans-serif !important;
  color: #212529;
  background-color: #ffffff;
}

/* Concrete Component CSS from design specs */
.button-primary {
  background: #009fe3;
  color: #ffffff;
  border-radius: 50px;
  padding: 10px 30px;
  font-size: 13px;
  border: none;
  cursor: pointer;
  transition: all 0.3s ease;
  display: inline-block;
}
.button-primary:hover {
  background: #ffc023;
  color: #ffffff;
}

.badge-pill {
  background: #009fe3;
  color: #ffffff;
  border-radius: 50px;
  padding: 10px 30px;
  font-size: 13px;
  display: inline-block;
}

/* Header & Brand Enhancements */
header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 999;
  line-height: 55px;
  padding-top: 15px;
  padding-bottom: 15px;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(8px);
  transition: background 0.4s ease-out, box-shadow 0.4s ease-out;
}
header.scroll {
  background: rgba(255, 255, 255, 0.98) !important;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
}
header .brand {
  display: inline-flex;
  align-items: center;
  height: 55px;
  text-decoration: none;
}
header .brand img.brand-logo {
  max-height: 52px;
  width: auto;
  max-width: 260px;
  object-fit: contain;
  transition: transform 0.3s ease;
}
header .brand:hover img.brand-logo {
  transform: scale(1.02);
}

/* Banner Slider Functionality */
.banner .slide_viewer {
  position: relative;
  overflow: hidden;
  border-radius: 15px;
}
.banner .slide_group {
  position: relative;
  width: 100%;
  height: 553px;
}
.banner .slide {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.7s ease-in-out, visibility 0.7s ease-in-out;
  display: block !important;
}
.banner .slide.active {
  opacity: 1;
  visibility: visible;
  z-index: 2;
}
.banner .slide img.lap {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 15px;
}
.banner .slide__text {
  position: absolute;
  bottom: 20%;
  left: 6%;
  right: 6%;
  color: #ffffff;
  z-index: 3;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.5);
}
.banner .slide__text h2 {
  font-size: 22px;
  font-weight: 400;
  color: #ffffff;
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.banner .slide__text h1 {
  font-size: 32px;
  font-weight: 600;
  color: #ffffff;
  line-height: 40px;
  margin-bottom: 15px;
}
.banner .slide__text p {
  font-size: 15px;
  color: #ffffff;
  line-height: 24px;
  max-width: 650px;
  margin-bottom: 25px;
}
.banner .slide__text p span {
  font-weight: 700;
  color: #20c997;
}
.banner .slide_buttons {
  position: absolute;
  top: 15px;
  left: 25px;
  z-index: 10;
}
.banner .slide_buttons a.slide_btn {
  font-size: 32px;
  line-height: 1;
  color: rgba(255, 255, 255, 0.6);
  cursor: pointer;
  user-select: none;
  margin-right: 6px;
  display: inline-block;
  transition: color 0.3s ease, transform 0.3s ease;
}
.banner .slide_buttons a.slide_btn.active {
  color: #009fe3;
  transform: scale(1.2);
}
.banner .slide_buttons a.slide_btn:hover {
  color: #ffffff;
}
.banner .directional_nav {
  position: absolute;
  bottom: 25px;
  right: 30px;
  z-index: 10;
  display: flex;
  gap: 10px;
}
.banner .directional_nav .btn {
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border-radius: 50px;
  color: #ffffff;
  background: #009fe3;
  border: 2px solid #ffffff;
  cursor: pointer;
  transition: all 0.3s ease;
  position: static;
}
.banner .directional_nav .btn:hover {
  background: #ffc023;
  border-color: #ffc023;
  transform: scale(1.05);
}

/* WhatsApp Floating Button */
.wppBtn {
  display: flex !important;
  align-items: center;
  justify-content: center;
  position: fixed;
  bottom: 30px;
  left: 30px;
  width: 58px;
  height: 58px;
  border-radius: 50px;
  background: #25d366;
  color: #ffffff !important;
  border: none;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.25);
  cursor: pointer;
  z-index: 9999;
  transition: all 0.3s ease;
  text-decoration: none;
}
.wppBtn:hover {
  background: #128c7e;
  transform: scale(1.1);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.35);
}
.wppBtn i {
  font-size: 32px;
  color: #ffffff;
  line-height: 1;
  margin: 0 !important;
}

/* Video Wrap Modal */
#video-wrap {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  z-index: 10001;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
#video-wrap.active {
  display: flex !important;
}
#video-wrap .video-container {
  width: 90%;
  max-width: 900px;
  position: relative;
  background: #000;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
}
#video-wrap .close-video {
  position: absolute;
  top: -45px;
  right: 0;
  width: 40px;
  height: 40px;
  background: #ffffff;
  border: none;
  border-radius: 50%;
  font-size: 22px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #000;
  z-index: 10;
  transition: transform 0.2s ease;
}
#video-wrap .close-video:hover {
  transform: scale(1.1);
}

/* Contact & Inquiry Modal */
.custom-modal-backdrop {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  z-index: 10002;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
.custom-modal-backdrop.active {
  display: flex !important;
}
.custom-modal-card {
  background: #ffffff;
  border-radius: 15px;
  width: 100%;
  max-width: 580px;
  padding: 35px;
  position: relative;
  box-shadow: 0 15px 45px rgba(0,0,0,0.25);
  animation: modalSlideIn 0.3s ease-out;
}
@keyframes modalSlideIn {
  from { opacity: 0; transform: translateY(-20px); }
  to { opacity: 1; transform: translateY(0); }
}
.custom-modal-close {
  position: absolute;
  top: 18px;
  right: 20px;
  background: none;
  border: none;
  font-size: 26px;
  color: #6c757d;
  cursor: pointer;
  line-height: 1;
}
.custom-modal-close:hover {
  color: #dc3545;
}

/* Responsive adjustments */
@media (max-width: 991.98px) {
  .banner .slide_group {
    height: 420px;
  }
  .banner .slide__text h1 {
    font-size: 24px;
    line-height: 32px;
  }
  header .lap {
    display: none !important;
  }
  header .mob {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
  }
}
@media (max-width: 767.98px) {
  .banner .slide_group {
    height: 380px;
  }
  .banner .slide img.lap {
    display: none !important;
  }
  .banner .slide img.mob {
    display: block !important;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
  .banner .slide__text {
    bottom: 12%;
    left: 5%;
    right: 5%;
  }
  .banner .slide__text h1 {
    font-size: 20px;
    line-height: 28px;
  }
  .banner .slide__text p {
    font-size: 13px;
    line-height: 18px;
    margin-bottom: 15px;
  }
}


