/* ==========================================================================
   RTL & ARABIC LANGUAGE SUPPORT
   ========================================================================== */
[dir="rtl"] {
  direction: rtl;
  text-align: right;
}

[dir="rtl"] body {
  font-family: 'Segoe UI', Tahoma, 'Open Sans', Arial, sans-serif !important;
}

[dir="rtl"] header .menu {
  float: left;
}

[dir="rtl"] header ul li {
  float: right;
}

[dir="rtl"] header ul li:not(:last-child) {
  margin-left: 25px;
  margin-right: 0;
}

[dir="rtl"] header .dropdown-content {
  text-align: right;
  left: auto;
  right: 0;
}

[dir="rtl"] header .dropdown-content a {
  border-left: none;
  border-right: 3px solid #ffffff;
}

[dir="rtl"] header .dropdown-content a:hover {
  border-left: none;
  border-right: 3px solid #009fe3;
}

[dir="rtl"] .banner .slide__text {
  left: auto;
  right: 6%;
  text-align: right;
}

[dir="rtl"] .banner .slide_buttons {
  left: auto;
  right: 25px;
}

[dir="rtl"] .banner .directional_nav {
  right: auto;
  left: 30px;
}

[dir="rtl"] .banner .text {
  left: auto;
  right: 8%;
  padding-left: 10px;
  padding-right: 0;
  text-align: right;
}

[dir="rtl"] .about p,
[dir="rtl"] .hse p,
[dir="rtl"] .product p,
[dir="rtl"] .news p {
  text-align: right;
}

[dir="rtl"] .card-body {
  text-align: right;
}

[dir="rtl"] .wppBtn {
  left: auto;
  right: 30px;
}

[dir="rtl"] .btn i {
  margin-left: 0 !important;
  margin-right: 10px !important;
  transform: rotate(180deg);
}

[dir="rtl"] .custom-modal-close {
  right: auto;
  left: 20px;
}

[dir="rtl"] .custom-modal-card {
  text-align: right;
}

[dir="rtl"] footer .content ul {
  text-align: right;
  padding-right: 0;
}

[dir="rtl"] footer .bot p {
  text-align: right;
}

/* Clickable elements hover & active feedback */
a, button, .card, .bx {
  cursor: pointer;
}
.card.h-100 {
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.card.h-100:hover {
  transform: translateY(-5px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.1) !important;
}
.card.h-100:hover .btn-link {
  color: #ffc023 !important;
}
.news .bx {
  cursor: pointer;
  transition: transform 0.3s ease;
}
.news .bx:hover {
  transform: translateY(-4px);
}
.top-contact-bar {
  background: #005373;
  color: #ffffff;
  font-size: 12px;
  padding: 6px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
}
.top-contact-bar a {
  color: #ffffff;
  text-decoration: none;
  margin-right: 20px;
  transition: color 0.2s ease;
}
.top-contact-bar a:hover {
  color: #ffc023;
}
[dir="rtl"] .top-contact-bar a {
  margin-right: 0;
  margin-left: 20px;
}

